import React from 'react';

const GCASHQR_BASE64 = 'data:image/jpeg;base64,';

export default function GCashQR({ width = 180, className = '' }) {
  return (
    <img
      src={GCASHQR_BASE64}
      alt="GCash / InstaPay QR Code"
      style={{ width: width + 'px', height: 'auto', display: 'block' }}
      className={`object-contain flex-shrink-0 ${className}`}
    />
  );
}

